scwin.fn_SetComboCode = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=STK_ISU_RSN_CD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.stkissrsncd.select.condition" + "&{P}param01=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD_1) + "&{P}param02=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD_1) + "&{P}param03=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD_1);
    dts_STK_ISU_RSN_CD.DataID = encodeURI(url);
    dts_STK_ISU_RSN_CD.Reset();
};
scwin.fn_list_sync_1 = function() {
    var url = "/listingCommon.do";
