        "&{P}param02=" + $c.stf.getObjectValue(rdo_MARKET_TP_CD_1) + // 시장구분
        "&{P}param03=" + $c.stf.getObjectValue(txb_ISUR_CD_1) + // 법인코드
        "&{P}param04=" + $c.stf.getObjectValue(txb_ISUR_CD_1) + // 법인코드
        "&{P}param05=" + $c.stf.getObjectValue(edt_SDate_1) + // 시작일자
        "&{P}param06=" + $c.stf.getObjectValue(edt_EDate_1) + // 종료일자
        "&{P}param07=" + $c.stf.getObjectValue(cmb_LIST_METHD_TP_CD_1) + // 상장방식
        "&{P}param08=" + $c.stf.getObjectValue(cmb_LIST_METHD_TP_CD_1) + // 상장방식
        "&{P}param09=" + $c.stf.getObjectValue(cmb_STKCERT_KIND_CD_1) + // 주식의종류
        "&{P}param10=" + $c.stf.getObjectValue(cmb_STKCERT_KIND_CD_1) + // 주식의종류
        "&{P}param11=" + $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD_1) + // 발행사유
        "&{P}param12=" + $c.stf.getObjectValue(cmb_STK_ISU_RSN_CD_1) + // 발행사유		
        "&{P}param13=" + $c.stf.getObjectValue(chb_STK_FUT_OPT_YN) + //주식선물/옵션대상자산여부
        "&{P}param14=" + $c.stf.getObjectValue(edt_SDate_1) + // 시작일자
        "&{P}param15=" + $c.stf.getObjectValue(edt_EDate_1); // 종료일자

    dts_List_1.DataID = encodeURI(url);
    dts_List_1.reset();
    $c.cm.ShowWin(grd_List_1);
};
