scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        //grd_List_1.GridToExcel("주권 발행내역", "", "8");
        $c.data.downloadGridViewOffice(grd_List_1, "주권 발행내역", "", 8, 0);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        //grd_List_2.GridToExcel("ETF 발행내역", "", "8");
        $c.data.downloadGridViewOffice(grd_List_2, "ETF 발행내역", "", 8, 0);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        //grd_List_3.GridToExcel("수익증권 발행내역", "", "8");
        $c.data.downloadGridViewOffice(grd_List_3, "수익증권 발행내역", "", 8, 0);
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        //grd_List_4.GridToExcel("신주인수권 발행내역", "", "8");
        $c.data.downloadGridViewOffice(grd_List_4, "신주인수권 발행내역", "", 8, 0);
    } else if (MaxTab_01.getSelectedTabIndex() == 5) {
        //grd_List_5.GridToExcel("ELW 발행내역", "", "8");
        $c.data.downloadGridViewOffice(grd_List_5, "ELW  발행내역", "", 8, 0);
    }
};
